function add(a, b):
    if b = 0: return a
    if a = 0: return b
    h = leading exponent of b
    kept = [(e,c) in a.terms with e > h]
    if some term (h, c) in a.terms:
        return kept ++ [(h, c + b.coeff0)] ++ b.terms[1:]
    return kept ++ b.terms

function omega_pow(a):
    if a = 0: return nat(1)
    return Ord([(a, 1)])

function tower(n):
    acc = 0
    repeat n times: acc = omega_pow(acc)
    return acc

